import{_ as t,o,c as r,a2 as l}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"快捷键与悬浮窗","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/panel.md","filePath":"zh/troubleshooting/panel.md","lastUpdated":1792942184000}'),s={name:"zh/troubleshooting/panel.md"};function n(i,e,a,g,h,p){return o(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="快捷键与悬浮窗" tabindex="-1">快捷键与悬浮窗 <a class="header-anchor" href="#快捷键与悬浮窗" aria-label="Permalink to &quot;快捷键与悬浮窗&quot;">​</a></h1><p>本页用于快捷键无效，或面板抢焦点、消失、在共享屏幕中被看到的情况。</p><h2 id="shortcuts" tabindex="-1">快捷键没反应 <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;快捷键没反应 {#shortcuts}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>其他程序先注册了同样的组合键（<a href="/meetcue/zh/troubleshooting/error-codes#mc-hk-001">MC-HK-001</a>）。</li><li>前台窗口属于以管理员身份运行的程序。</li><li>游戏或播放器处于独占全屏。</li><li>MeetCue 没有在运行。</li></ol><p><strong>检查</strong></p><ol><li>在任务栏通知区域查找 MeetCue 图标。</li><li>打开 <strong>设置 › 快捷键</strong>，查看是否有标红的行。</li><li>点击桌面后再试一次快捷键。</li></ol><p><strong>解决</strong></p><ol><li>把标红的快捷键改成未被占用的组合。</li><li>Windows 不会把管理员窗口里的按键传给普通程序。这类窗口在前台时请用面板按钮，或不要以管理员身份运行该程序。</li><li>把全屏程序切换为窗口或无边框窗口模式。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="focus" tabindex="-1">点击面板后会议窗口失去焦点 <a class="header-anchor" href="#focus" aria-label="Permalink to &quot;点击面板后会议窗口失去焦点 {#focus}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>面板里的输入框或菜单需要键盘焦点。</li><li>远程桌面或虚拟机的窗口管理忽略了“不激活”样式。</li></ol><p><strong>检查</strong></p><ol><li>点击一条要点，然后在会议聊天框里打字，文字应该进入聊天框。</li></ol><p><strong>解决</strong></p><ol><li>会议中用快捷键代替鼠标。</li><li>打开 <strong>设置 › 通用 › 鼠标穿透面板</strong>，面板将完全不响应鼠标。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="position" tabindex="-1">面板跑到屏幕外或找不到 <a class="header-anchor" href="#position" aria-label="Permalink to &quot;面板跑到屏幕外或找不到 {#position}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>面板原本在外接显示器上，而显示器已断开。</li><li>面板被隐藏了；<code>Ctrl+Alt+H</code> 在完整 → 迷你 → 隐藏之间循环。</li></ol><p><strong>检查</strong></p><ol><li>按一两次 <code>Ctrl+Alt+H</code>。</li></ol><p><strong>解决</strong></p><ol><li>右键托盘图标，选择 <strong>重置面板位置</strong>。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="screen-share" tabindex="-1">共享屏幕时对方能看到面板 <a class="header-anchor" href="#screen-share" aria-label="Permalink to &quot;共享屏幕时对方能看到面板 {#screen-share}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li><strong>共享屏幕时隐藏面板</strong> 被关闭了。</li><li>录制方式直接采集显示输出。部分录屏软件、远程协助工具和外接采集设备会这样做。</li><li>Windows 10 2004 之前的版本不支持对截屏隐藏窗口。</li></ol><p><strong>检查</strong></p><ol><li>打开 <strong>设置 › 通用</strong>，查看 <strong>共享屏幕时隐藏面板</strong>。</li><li>向自己或同事共享屏幕，或用 <code>Win+Shift+S</code> 截图：截图中不应出现面板。</li></ol><p><strong>解决</strong></p><ol><li>打开这项设置。</li><li>只共享单个窗口而不是整个屏幕。面板不属于其他程序的窗口，不会被共享出去。</li><li>无法确定隐藏是否生效时，改用迷你条，或用 <code>Ctrl+Alt+H</code> 隐藏面板。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p>',34)])])}const d=t(s,[["render",n]]);export{u as __pageData,d as default};
